definition.script:
pipeline {
    agent { label 'built-in' }
    stages {
        stage('Checkout') {
            steps {
                sh 'git config --global http.sslVerify false'
                git branch: 'master', url: 'https://admin:admin@gitblit:8443/r/python_test.git'
            }
        }
        stage('Install') {
            steps {
                sh '''
                python3 -m venv venv
                . venv/bin/activate
                pip install -r requirements.txt || echo "No dependencies to install"
                '''
            }
        }
        stage('Test') {
            steps {
                sh '''
                . venv/bin/activate
                python3 test.py || echo "No tests found"
                '''
            }
        }
        stage('Package') {
            steps {
                sh '''
                ARTIFACT_DIR="/var/jenkins_home/artifacts"
                mkdir -p $ARTIFACT_DIR
                tar -czvf $ARTIFACT_DIR/python_app.tar.gz .
                echo "Artifact saved to $ARTIFACT_DIR/python_app.tar.gz"
                '''
            }
        }
    }
    post {
        success {
            build job: 'python_test_deploy', wait: false
        }
    }
}
